package diagnose

// Rule documents one rule: what it detects and from which evidence. docs/rules.md is generated from this list.
type Rule struct {
	ID       string
	Title    string
	Severity Severity
	Detects  string
	Evidence string
}

// Rules is every rule kube-diagnose can report, in ID order. IDs are stable: a rule is retired, never renumbered.
var Rules = []Rule{
	{"KD100", "Image cannot be pulled", Critical, "A container waits in ErrImagePull or ImagePullBackOff for a reason none of KD101-KD103 recognises.", "The container's waiting state and the newest pull-failure event."},
	{"KD101", "Image does not exist", Critical, "The registry answered that the image's tag or digest does not exist.", "The waiting state, and the pull-failure event whose message says not found or manifest unknown."},
	{"KD102", "Registry refused the image pull", Critical, "The registry refused the pull: no credentials, wrong credentials, or a repository that does not exist and is reported as access denied.", "The pull-failure event saying unauthorized, denied, 401/403 or insufficient_scope, and whether the pod has imagePullSecrets."},
	{"KD103", "Registry cannot be reached", Critical, "The node could not reach the registry: DNS, connection or TLS failure, a certificate the node does not trust (x509), or a registry that speaks plain HTTP.", "The pull-failure event saying no such host, i/o timeout, connection refused or TLS handshake timeout."},
	{"KD104", "Image reference is invalid", Critical, "The image field is not a valid reference.", "The container waiting in InvalidImageName."},
	{"KD105", "Registry rate-limits the image pull", Critical, "The registry refused the pull because a pull quota is used up (429 Too Many Requests), as Docker Hub does for anonymous pulls.", "The pull-failure event with toomanyrequests or 429."},
	{"KD106", "Image pull secret does not exist", Critical, "The registry refused the pull, and a Secret the pod lists in imagePullSecrets does not exist, so the pull went without credentials.", "The pull-failure event, the FailedToRetrieveImagePullSecret event when present, and the Secret list (names only)."},
	{"KD107", "Image pull secret has the wrong type", Critical, "The registry refused the pull, and a Secret the pod lists in imagePullSecrets is not of type kubernetes.io/dockerconfigjson or dockercfg, so the kubelet ignored it.", "The pull-failure event and the Secret's type and key names (never values)."},
	{"KD108", "Image is not on the node and may not be pulled", Critical, "A container's imagePullPolicy is Never and its image is not on the node, so the kubelet will not start it (ErrImageNeverPull).", "The container's waiting state and its imagePullPolicy."},
	{"KD109", "Image has no build for the node's platform", Critical, "The image exists, but its index has no manifest for the node's OS and architecture (no match for platform in manifest), so the pull fails.", "The pull-failure event and the node's kubernetes.io/arch label."},
	{"KD110", "Container keeps crashing", Critical, "A container exits and is restarted (CrashLoopBackOff), or a Job's container exits non-zero. The exit code is explained and the log line that reads like the error is quoted. Exit code 0 in a long-running workload is called out.", "The last terminated state (exit code, reason) and the tail of the previous run's log."},
	{"KD111", "Container runs out of memory", Critical, "A container is killed for using more memory than its limit (OOMKilled). Critical while it crash-loops, a warning while it runs between kills.", "The terminated state with reason OOMKilled, and the container's memory limit."},
	{"KD112", "Liveness probe kills the container", Critical, "The kubelet restarts a container because its liveness or startup probe fails. When the probe's port is not one the container declares, it says so, and when an exec probe's command is not in the image, it names the command.", "Unhealthy and Killing events naming the probe, the exit code 137 or 143, and the probe spec."},
	{"KD113", "Image built for another CPU architecture", Critical, "The container's binary fails with exec format error: the image is for another architecture than the node.", "The start error or the log line with exec format error."},
	{"KD114", "Command not found in the image", Critical, "The container's command does not exist in the image.", "The StartError or RunContainerError saying executable file not found, and the container's command."},
	{"KD115", "Init container fails", Critical, "An init container exits non-zero, so the app containers never start.", "The init container's terminated state and the tail of its log."},
	{"KD116", "Lifecycle hook fails", Critical, "A container's postStart hook fails, so the kubelet kills the container each time it starts and it crash-loops.", "FailedPostStartHook events naming the container, with the hook's error."},
	{"KD117", "Image runs as root but the pod requires non-root", Critical, "The pod sets runAsNonRoot and the image runs as root, or names a non-numeric user the kubelet cannot check, so the container is never created.", "The container's CreateContainerConfigError message."},
	{"KD118", "Container writes to its read-only root filesystem", Critical, "A container with readOnlyRootFilesystem: true exits because it writes to its root filesystem; the path it writes to is named so a volume can be mounted there.", "The log line with read-only file system, and the container's securityContext."},
	{"KD119", "Init container never finishes", Critical, "An init container has been running for more than two minutes in a pending pod, so the app containers never start; usually it loops waiting for a dependency, and its log names it.", "The init container's running state and the tail of its current log."},
	{"KD120", "Readiness probe failing", Critical, "A running container never becomes ready because its readiness probe fails, so its Services send it no traffic. When an exec probe's command is not in the image, it names the command.", "Unhealthy events for the readiness probe, the container's ready state, and the probe spec."},
	{"KD121", "Container looks up a Service that does not exist", Critical, "A container exits after failing to resolve a host name that names a Service (name, name.namespace or name.namespace.svc.cluster.local), and there is no such Service.", "The failed lookup in the container's log, and the Service list showing it is absent."},
	{"KD122", "Port is already in use", Critical, "A container exits because the port it binds is taken (address already in use); when another container of the same pod declares that port, it is named.", "The log line with address already in use, and the ports the pod's containers declare."},
	{"KD123", "NetworkPolicy blocks the pod's DNS lookups", Critical, "A container exits after a failed DNS lookup, and the egress NetworkPolicies that select its pod allow nothing to port 53.", "The failed lookup in the container's log, and the policy's egress rules."},
	{"KD124", "Container connects to a Service with no ready pods", Critical, "A container exits after a refused connection to a Service of its namespace (by name or cluster IP) that has no ready pods; the cluster refuses connections to a Service without endpoints.", "The refused connection in the container's log, and the Service's endpoints."},
	{"KD125", "Container needs a ServiceAccount token that is not mounted", Critical, "A container exits because it cannot read /var/run/secrets/kubernetes.io/serviceaccount, while the pod or its ServiceAccount sets automountServiceAccountToken: false.", "The crashing container's log line and the automountServiceAccountToken field that turned the token off."},
	{"KD126", "ServiceAccount lacks RBAC permission", Critical, "A container exits after the API server refuses its ServiceAccount a request (forbidden: cannot list resource ...); the verb, resource and scope are named, and the fix gives the Role and RoleBinding to create.", "The crashing container's log line quoting the API server's denial, and the cluster's bindings."},
	{"KD127", "NetworkPolicy blocks the connection to a Service", Critical, "A container exits after its connection to a Service of its namespace times out, the Service has ready pods, and NetworkPolicies on the client's egress or the backends' ingress allow nothing between them on that port. Peers chosen by namespace selector or IP block count as allowed.", "The crashing container's log line with the timeout, and the namespace's NetworkPolicies."},
	{"KD128", "Readiness gate is not met", Critical, "A pod has run for two minutes with every container ready, but is not Ready because a readiness gate condition is missing or not True: the controller that should set it (often a load balancer controller) has not.", "The pod's readinessGates and conditions."},
	{"KD129", "Probe command is not in the image", Warning, "A running container's liveness or startup probe runs a command the image does not have. The kubelet reports the probe as errored and ignores the result, so it never restarts the container: the probe silently checks nothing.", "Unhealthy events saying the probe errored with executable file not found, and the probe spec."},
	{"KD130", "ConfigMap does not exist", Critical, "A container's env, envFrom or a volume refers to a ConfigMap that does not exist.", "CreateContainerConfigError or a FailedMount event, and the ConfigMap list showing it is absent."},
	{"KD131", "Secret does not exist", Critical, "A container's env, envFrom or a volume refers to a Secret that does not exist.", "CreateContainerConfigError or a FailedMount event, and the Secret list (names only) showing it is absent."},
	{"KD132", "Key missing from ConfigMap or Secret", Critical, "A container reads a key that the ConfigMap or Secret does not have.", "The kubelet's couldn't-find-key message, and the object's key names (never values)."},
	{"KD133", "Volume cannot be mounted", Critical, "A pod is stuck creating its containers because a volume fails to mount, for a reason KD130-KD132 do not cover.", "The FailedMount event."},
	{"KD134", "Pod sandbox cannot be created", Critical, "A pod is on a node but no container has started, because the node cannot create its sandbox: the network plugin fails, or the node has no pod IP address left. The containers say only ContainerCreating.", "The newest FailedCreatePodSandBox event."},
	{"KD135", "hostPath does not exist on the node", Critical, "A hostPath volume with a type (Directory, File, Socket and so on) names a path the node does not have, so the volume cannot be mounted and the pod stays in ContainerCreating.", "The FailedMount event saying hostPath type check failed, and the volume spec."},
	{"KD136", "CSI driver is not running", Critical, "A volume uses a CSI driver that is not registered on the pod's node, or whose attacher never answers, so the volume is not mounted and the pod stays in ContainerCreating.", "The FailedMount or FailedAttachVolume event naming the driver, and the drivers each CSINode lists."},
	{"KD137", "Container is denied access to a mounted volume", Critical, "A container exits after permission denied on a path under one of its volume mounts: the volume's files belong to another user than the one it runs as. hostPath volumes, which fsGroup does not change, and Secret or ConfigMap file modes are called out.", "The log line with permission denied and the path, the volume mount and volume it falls under, and the pod's runAsUser and fsGroup."},
	{"KD138", "Container writes to a read-only volume", Critical, "A container exits after read-only file system on a path under a ConfigMap, Secret, projected or downward API volume, which the kubelet always mounts read-only, or under a mount with readOnly: true.", "The log line with read-only file system and the path, and the volume mount and volume it falls under."},
	{"KD139", "Container configuration is invalid", Critical, "CreateContainerConfigError for a reason KD130-KD132 do not cover.", "The container's waiting message."},
	{"KD140", "No node has enough of a resource", Critical, "The scheduler finds no node with enough free cpu, memory, pods or an extended resource such as GPUs. When the request exceeds every node's allocatable, it says the pod can never fit.", "The pod's PodScheduled condition, its requests, and the largest node's allocatable."},
	{"KD141", "No node matches the pod's node selector", Critical, "No node has the labels the pod's nodeSelector or node affinity requires.", "The scheduler's message, the pod's nodeSelector, and the node list."},
	{"KD142", "Nodes have taints the pod does not tolerate, or are cordoned", Critical, "Nodes reject the pod because of taints it does not tolerate, or because they are cordoned.", "The scheduler's message naming the taint, and the nodes' taints."},
	{"KD143", "Pod waits for a PersistentVolumeClaim", Critical, "A pod cannot be scheduled until its claim is bound; the pod is listed under the claim's own finding when there is one.", "The scheduler's unbound-claim message and the claim's phase."},
	{"KD144", "Pod spread or affinity rules cannot be met", Critical, "The scheduler rejects every node because of the pod's topology spread constraints or required pod (anti-)affinity, for example more replicas than topology domains with whenUnsatisfiable: DoNotSchedule.", "The scheduler's message and the pod's constraints."},
	{"KD145", "Host port is taken on every node", Critical, "The pod asks for a hostPort that another pod already uses on every node the scheduler considered.", "The scheduler's message and the pod's host ports."},
	{"KD146", "Pod is held by a scheduling gate", Critical, "A pod has carried scheduling gates for more than two minutes, so the scheduler has not looked at it; it has no events and no error. Kueue's gate is recognised and the pod's queue named.", "The PodScheduled condition with reason SchedulingGated and the pod's schedulingGates."},
	{"KD148", "Pod waits for a scheduler that is not running", Critical, "A pod that names a scheduler other than the default (schedulerName) has had no scheduling decision for two minutes: that scheduler is not installed, not running, or does not handle the namespace.", "The pod's schedulerName, the absence of a PodScheduled condition, and its age."},
	{"KD149", "Pod cannot be scheduled", Critical, "The scheduler rejects every node for a reason KD140-KD143 do not cover; its message is quoted.", "The pod's PodScheduled condition or FailedScheduling event."},
	{"KD150", "StorageClass does not exist", Critical, "A claim asks for a StorageClass that does not exist.", "The claim's storageClassName and the StorageClass list."},
	{"KD151", "No default StorageClass", Critical, "A claim names no StorageClass and the cluster has no default, so nothing provisions it.", "The claim, the StorageClass list, and the absence of an Available static volume."},
	{"KD152", "Volume is not provisioned", Critical, "A claim stays Pending: provisioning failed or its provisioner never answered.", "ProvisioningFailed, ExternalProvisioning or FailedBinding events on the claim."},
	{"KD153", "PersistentVolumeClaim does not exist", Critical, "A pod mounts a claim that does not exist.", "The scheduler's message and the claim list."},
	{"KD154", "Volume is pinned to a node or zone the pod cannot use", Critical, "The pod's PersistentVolume has node affinity (a zone or a local node) that none of the nodes the pod can use match.", "The scheduler's message and the bound PersistentVolume's nodeAffinity."},
	{"KD155", "Volume is attached to another node", Critical, "A pod waits in ContainerCreating because its ReadWriteOnce volume is still attached to another node, typically while an older pod still holds it during a rolling update.", "The FailedAttachVolume event with the Multi-Attach error."},
	{"KD156", "StorageClass cannot provide the access mode", Critical, "A claim stays Pending because its provisioner refuses the access mode it asks for, typically ReadWriteMany on node-local or block storage.", "The claim's access modes and the ProvisioningFailed event naming the access mode."},
	{"KD157", "Claim names a volume it cannot bind to", Critical, "A pending claim names its PersistentVolume (volumeName) and cannot bind to it: the volume does not exist, is reserved for another claim, is Released with the old claim's UID, or has another StorageClass or less capacity. The controller writes no event for most of these.", "The claim's volumeName and the PersistentVolume's claimRef, phase, class and capacity."},
	{"KD158", "Volume resize failed", Warning, "A bound claim asks for more storage than its volume has and the resizer reports a failure, so the volume did not grow; the claim stays Bound and nothing else looks wrong until the disk fills.", "The claim's requested and actual capacity, and the newest VolumeResizeFailed or FileSystemResizeFailed event."},
	{"KD160", "Service selects no pods", Critical, "A Service's selector matches no pod and no workload's pod template, and the pod labels closest to it are named. When the pods' workload is scaled to 0 replicas and an Ingress still routes to the Service, that is said instead, as a warning.", "The Service's selector and the labels of the pods in the namespace."},
	{"KD161", "Service targets a port the pods do not have", Critical, "A Service's targetPort names a port no selected container declares, so the Service has no endpoints although its pods are ready.", "The Service's ports, the pods' named ports, and the empty EndpointSlice."},
	{"KD162", "Service has no ready pods", Critical, "A Service selects pods but none is ready, for a reason no other finding explains. When a pod finding explains it, the Service is listed under that finding instead.", "The selected pods and their readiness."},
	{"KD163", "NetworkPolicy blocks all traffic to a Service", Warning, "Every ready pod behind a Service is selected by ingress NetworkPolicies with no rules, so nothing can connect. A warning, because a closed Service can be intended.", "The policy's pod selector and empty ingress, and the Service's pods."},
	{"KD164", "Service targets a port the pods do not declare", Warning, "A numeric targetPort that none of the selected containers declares, while they declare others: the usual shape of a wrong targetPort. A warning, because declaring ports is optional.", "The Service's ports and the pods' declared ports."},
	{"KD165", "Ingress sends traffic to a Service that does not exist", Critical, "An Ingress rule or default backend names a Service that does not exist in its namespace, so the controller answers those paths with an error, usually 503.", "The Ingress's backends and the Service list."},
	{"KD166", "Ingress sends traffic to a port the Service does not have", Critical, "An Ingress backend names a port number or port name the Service does not expose (often the container's port instead of the Service's), so the controller has no endpoints for it.", "The Ingress's backends and the Service's ports."},
	{"KD167", "Ingress has no controller", Critical, "An Ingress names an IngressClass the cluster does not have, or names none while no class is marked default, so no controller serves it. Ingresses with the legacy kubernetes.io/ingress.class annotation are skipped.", "The Ingress's ingressClassName and the IngressClass list."},
	{"KD168", "LoadBalancer Service has no external address", Warning, "A Service of type LoadBalancer has had no external address for more than two minutes: no load balancer implementation serves the cluster, or the one there fails; its error is quoted when it reports one.", "The Service's type and status.loadBalancer, and SyncLoadBalancerFailed events."},
	{"KD169", "Ingress TLS Secret is missing or has no certificate", Critical, "An Ingress's tls entry names a Secret that does not exist, or one without tls.crt and tls.key, so the controller serves its default certificate for those hosts.", "The Ingress's tls entries, and the Secret list or the Secret's type and key names (never values)."},
	{"KD170", "ResourceQuota is exhausted", Critical, "A controller cannot create pods because a ResourceQuota is used up or requires requests and limits the pods do not set.", "The controller's FailedCreate event and the quota's usage."},
	{"KD171", "ServiceAccount does not exist", Critical, "A controller cannot create pods because their ServiceAccount does not exist.", "The FailedCreate event and the ServiceAccount list."},
	{"KD172", "Pod Security admission rejects the pods", Critical, "Pods violate the namespace's Pod Security level and are rejected; each violation is quoted.", "The FailedCreate event and the namespace's pod-security labels."},
	{"KD173", "Admission webhook rejects the pods", Critical, "An admission webhook denies the controller's pods.", "The FailedCreate event naming the webhook."},
	{"KD174", "LimitRange rejects the pods", Critical, "A controller cannot create pods because their requests or limits fall outside the namespace LimitRange's minimum, maximum or limit-to-request ratio.", "The controller's FailedCreate event quoting each violated bound."},
	{"KD175", "PriorityClass does not exist", Critical, "A controller cannot create pods because their priorityClassName names a PriorityClass that does not exist.", "The controller's FailedCreate event."},
	{"KD176", "HPA cannot read its metrics", Warning, "A HorizontalPodAutoscaler cannot compute replicas because it cannot read its metrics: no metrics API (metrics-server), a container without the resource request utilization needs, or a custom metric no adapter serves. The workload looks healthy but does not scale.", "The HPA's ScalingActive condition."},
	{"KD177", "HPA is held at its maximum", Warning, "A HorizontalPodAutoscaler computes more replicas than maxReplicas allows, so the workload runs under more load than its scaling target.", "The HPA's ScalingLimited condition with reason TooManyReplicas."},
	{"KD178", "HPA targets a workload that does not exist", Warning, "A HorizontalPodAutoscaler's scaleTargetRef names a workload that does not exist, so it scales nothing.", "The HPA's AbleToScale condition with reason FailedGetScale."},
	{"KD179", "Controller cannot create pods", Critical, "A controller's FailedCreate event for a reason KD170-KD173 do not cover.", "The FailedCreate event."},
	{"KD180", "Job failed", Critical, "A Job failed (backoff limit or deadline) and no pod is left to show why.", "The Job's Failed condition."},
	{"KD181", "Deployment rollout stalled", Warning, "A Deployment passed its progress deadline and no pod finding explains it.", "The Progressing condition with ProgressDeadlineExceeded."},
	{"KD182", "StatefulSet's governing Service is missing or not headless", Warning, "A StatefulSet's serviceName names a Service that does not exist, or one with a cluster IP, so its pods get no stable DNS names and peers that find each other by name cannot.", "The StatefulSet's serviceName, and the Service list or the Service's clusterIP."},
	{"KD183", "RuntimeClass does not exist", Critical, "A controller cannot create pods because their runtimeClassName names a RuntimeClass that does not exist.", "The controller's FailedCreate event saying RuntimeClass not found."},
	{"KD184", "Deployment rollout is paused", Warning, "A Deployment has spec.paused: true while some of its replicas do not run the current template or are not ready, so the change never rolls out; critical when no replica is ready, as for a Deployment created paused, which creates no pods.", "The Deployment's paused field, updated and ready counts, and its DeploymentPaused condition."},
	{"KD185", "PodDisruptionBudget allows no disruptions", Warning, "A PodDisruptionBudget allows 0 disruptions while every pod it covers is healthy (minAvailable equal to the replica count, or maxUnavailable 0), so node drains and cluster upgrades wait on it forever.", "The budget's spec and status."},
	{"KD186", "PodDisruptionBudget selects no pods", Warning, "A PodDisruptionBudget's selector matches no pod and no workload's pod template, so it protects nothing; the closest pod labels are named.", "The budget's selector and expectedPods, and the pod labels in the namespace."},
	{"KD187", "Job is suspended", Info, "A Job has had spec.suspend: true for more than two minutes, so it runs no pods. When Kueue manages it, it waits for admission and the LocalQueue is named, as a warning.", "The Job's suspend field and Suspended condition."},
	{"KD188", "CronJob skips runs while the last one is still running", Warning, "A CronJob with concurrencyPolicy Forbid starts no Job because the last one is still running; the controller's JobAlreadyActive events count the runs skipped.", "The JobAlreadyActive event, the CronJob's schedule, policy and active Job, and the active Job's start time."},
	{"KD189", "CronJob is suspended", Info, "A CronJob has spec.suspend: true, so its schedule starts no Jobs; when it last started one is said.", "The CronJob's spec.suspend and status.lastScheduleTime."},
	{"KD190", "Node is not ready", Critical, "A node's Ready condition is False or Unknown; the pods on it are listed.", "The node's Ready condition."},
	{"KD191", "Node is under pressure", Warning, "A node reports MemoryPressure, DiskPressure, PIDPressure or NetworkUnavailable.", "The node's condition."},
	{"KD192", "Pod was evicted", Warning, "The kubelet evicted a pod, usually because the node ran low on memory or disk; the resource is named.", "The pod's Evicted status and message."},
	{"KD193", "Container exceeded its ephemeral storage limit", Warning, "The kubelet evicted a pod because a container, or the pod as a whole, wrote more to local disk than its ephemeral-storage limit.", "The pod's Evicted status and message."},
	{"KD194", "Pod is stuck terminating", Warning, "A deleted pod is still there more than two minutes after its grace period ended: a finalizer nobody removes, a node that is not ready, or a kubelet that cannot stop it.", "The pod's deletionTimestamp, finalizers and node, and the node's Ready condition."},
	{"KD200", "Command is not executable", Critical, "The runtime cannot execute the container's command (permission denied), or a shell exits 126 on a script under a volume mount. When the file comes from a ConfigMap, Secret or projected volume, its mode is named: those files are 0644 unless defaultMode or the item's mode says otherwise.", "The StartError or the log line with permission denied, and the volume's defaultMode and item modes."},
	{"KD230", "File is missing from a ConfigMap or Secret volume", Critical, "A container exits after no such file or directory on a path under a ConfigMap or Secret volume that has no such key, or whose items do not project it, or its command is such a path. The keys it has are listed, which shows a misnamed key at a glance.", "The log line or start error naming the path, the volume mount, and the object's key names (never values)."},
	{"KD240", "Pod is bound to a node that does not exist", Critical, "A pending pod's spec.nodeName names a node the cluster does not have. nodeName bypasses the scheduler, so no event says anything: no kubelet runs the pod, and the pod garbage collector deletes it while its controller makes another.", "The pod's spec.nodeName and the node list."},
	{"KD260", "ExternalName Service names an IP address", Warning, "A Service of type ExternalName has an IP address as its externalName. Cluster DNS answers with a CNAME to that address written as a name, which resolves to nothing, so the Service's clients get no address.", "The Service's type and externalName."},
}

// RuleByID finds a rule.
func RuleByID(id string) (Rule, bool) {
	for _, r := range Rules {
		if r.ID == id {
			return r, true
		}
	}
	return Rule{}, false
}
